{
  "category_edits": [
    {
      "category": "learning_objective",
      "rationale": "Replace weighted BPR with binary focal loss (gamma=1), equally weighting positive and negative examples. This may focus learning on difficult predictions while preserving existing samples, masks, architecture, scoring, and training settings across all four category models.",
      "edits": [
        {
          "find": "    weights = torch.softmax(valid_neg.detach(), dim=0)\n    pairwise_loss = torch.nn.functional.softplus(valid_neg - valid_pos)\n    return (weights * pairwise_loss).sum()",
          "replace": "    positive_loss = torch.sigmoid(-valid_pos) * torch.nn.functional.softplus(-valid_pos)\n    negative_loss = torch.sigmoid(valid_neg) * torch.nn.functional.softplus(valid_neg)\n    return 0.5 * (positive_loss.mean() + negative_loss.mean())"
        }
      ]
    }
  ],
  "change_summary": "Apply equally weighted binary focal loss with gamma=1 to existing valid positive and negative scores. Inference and checkpoint formats remain unchanged."
}
